"});\n var h='<div class=\"card\"><div class=\"top\"><div><h3>Editor do formulário dos coordenadores</h3><p class=\"muted\">Gerencie título, enunciado, alternativas e obrigatoriedade. A Secretaria pode corrigir perguntas publicadas. Cada mudança cria uma nova versão, e avaliações já iniciadas preservam as perguntas originais. Rascunhos novos exigem publicação explícita.</p><p><span class=\"pill warn\">'+active.filter(q=>q.status===\"rascunho\").length+' em rascunho</span> · '+active.length+' perguntas ativas</p></div><button class=\"btn primary small\" onclick=\"newQ()\">+ Nova pergunta</button></div></div>';\n h+='<div class=\"card\" style=\"margin:12px 0\"><h3>Feedback dos coordenadores ao pastor</h3><p class=\"muted\">Não existe autoavaliação de desempenho. Cada coordenador preenche sua Manifestação de Interesse: continuar, permanecer, mudar de congregação/setor ou sair, e informar o motivo.</p><span class=\"pill ok\">Manifestação independente das avaliações</span></div>';\n h+=active.map(function(q){\n  var kind=q.tipo_resposta===\"escolha_unica\"?\"Múltipla escolha\":\"Resposta discursiva\";\n  var opts=q.tipo_resposta===\"escolha_unica\"?'<div class=\"muted\" style=\"margin-top:8px\">Alternativas: '+e((q.opcoes||[]).join(\" · \"))+'</div>':\"\";\n  return'<div class=\"question\"><div class=\"top\"><div><span class=\"pill '+(q.status===\"rascunho\"?\"warn\":\"ok\")+'\">'+e(q.status)+'</span> <span class=\"pill\">'+e(kind)+'</span> '+(q.obrigatoria?'<span class=\"pill\">Obrigatória</span>':'<span class=\"pill\">Opcional</span>')+'</div><span class=\"muted\">Código '+e(q.codigo)+'</span></div><h4 style=\"margin-top:9px\">'+e(q.ordem)+'. '+e(q.titulo)+'</h4><p style=\"white-space:pre-wrap\">'+e(q.enunciado)+'</p>'+opts+'<div class=\"actions\"><button class=\"btn ghost small\" onclick=\"editQ(&quot;'+e(q.id)+'&quot;)\">Editar pergunta</button>'+(q.status===\"rascunho\"?'<button class=\"btn primary small\" onclick=\"publishQ(&quot;'+e(q.id)+'&quot;)\">Publicar</button><button class=\"btn danger small\" onclick=\"archiveQ(&quot;'+e(q.id)+'&quot;)\">Arquivar</button>':'')+'</div></div>'\n }).join(\"\");\n if(archived.length)h+='<details class=\"card\" style=\"margin-top:12px\"><summary>Arquivo de perguntas ('+archived.length+')</summary>'+archived.map(function(q){return'<p>'+e(q.codigo)+' · '+e(q.titulo)+' · '+e(q.status)+'</p>'}).join(\"\")+'</details>';\n return h;\n}\nfunction editorMarkup(q,isNew){\n var kind=q?.tipo_resposta||\"texto_longo\",isChoice=kind===\"escolha_unica\",choices=Array.isArray(q?.opcoes)?q.opcoes.join(\"\\n\"):\"\";\n var h='<div class=\"ey\">FORMULÁRIO DO COORDENADOR</div><h2>'+(isNew?\"Nova pergunta\":\"Editar pergunta \"+e(q.ordem))+'</h2><p class=\"muted\">'+(isNew?\"Crie uma pergunta em rascunho. A publicação é separada.\":q.status===\"rascunho\"?\"As alterações ficam salvas em rascunho.\":\"Pergunta publicada: você pode corrigir antes da primeira avaliação. Depois será necessário versionamento.\")+'</p>';\n h+='<div class=\"field\"><label>Título da pergunta</label><input id=\"qt\" maxlength=\"180\" value=\"'+e(q?.titulo||\"\")+'\" placeholder=\"Ex.: Relacionamento com a congregação\"></div>';\n h+='<div class=\"field\"><label>Pergunta exibida ao coordenador</label><textarea id=\"qe\" rows=\"6\" maxlength=\"4000\" placeholder=\"Escreva aqui exatamente o que o coordenador deverá responder.\">'+e(q?.enunciado||\"\")+'</textarea></div>';\n h+='<div class=\"field\"><label>Tipo de resposta</label><select id=\"qtype\" onchange=\"toggleQChoices()\"><option value=\"texto_longo\" '+(kind===\"texto_longo\"?\"selected\":\"\")+'>Resposta discursiva (texto livre)</option><option value=\"escolha_unica\" '+(isChoice?\"selected\":\"\")+'>Múltipla escolha (uma alternativa)</option></select></div>';\n h+='<div class=\"field\" id=\"qchoiceswrap\" style=\"'+(isChoice?\"\":\"display:none\")+'\"><label>Alternativas, uma por linha</label><textarea id=\"qchoices\" rows=\"6\" placeholder=\"Opção 1&#10;Opção 2&#10;Opção 3\">'+e(choices)+'</textarea><p class=\"muted\">Informe de 2 a 12 alternativas distintas.</p></div>';\n h+='<div class=\"field\"><label style=\"display:flex;gap:8px;align-items:center\"><input id=\"qrequired\" type=\"checkbox\" style=\"width:auto\" '+(q?.obrigatoria!==false?\"checked\":\"\")+'> Resposta obrigatória</label></div>';\n h+='<div class=\"actions\"><button class=\"btn ghost\" onclick=\"closeM()\">Cancelar</button><button class=\"btn primary\" onclick=\"'+(isNew?\"createQ()\":\"saveQ(&quot;\"+e(q.id)+\"&quot;)\")+'\">'+(isNew?\"Criar rascunho\":\"Salvar alterações\")+'</button></div>';\n return h;\n}\nwindow.toggleQChoices=function(){\n var el=document.getElementById(\"qchoiceswrap\"),sel=document.getElementById(\"qtype\");\n if(el&&sel)el.style.display=sel.value===\"escolha_unica\"?\"\":\"none\";\n};\nwindow.editQ=function(id){\n var q=S.data.questions.find(function(x){return x.id===id});\n if(!q){toast(\"Pergunta não encontrada.\");return}\n box.innerHTML=editorMarkup(q,false);back.classList.add(\"show\");\n};\nwindow.newQ=function(){box.innerHTML=editorMarkup(null,true);back.classList.add(\"show\")};\nfunction questionPayload(){\n var title=document.getElementById(\"qt\").value.trim(),text=document.getElementById(\"qe\").value.trim(),type=document.getElementById(\"qtype\").value,required=document.getElementById(\"qrequired\").checked;\n if(!title||!text)throw new Error(\"Preencha o título e a pergunta.\");\n var options=null;\n if(type===\"escolha_unica\"){\n  options=document.getElementById(\"qchoices\").value.split(/\\r?\\n/).map(v=>v.trim()).filter(Boolean);\n  if(options.length<2||options.length>12||new Set(options.map(v=>v.toLowerCase())).size!==options.length)throw new Error(\"Informe de 2 a 12 alternativas diferentes.\");\n }\n return{titulo:title,enunciado:text,tipo_resposta:type,opcoes:options,obrigatoria:required};\n}\nwindow.saveQ=async function(id){\n try{var d=questionPayload();await api(\"update_question\",Object.assign({id:id},d));closeM();toast(\"Pergunta salva no rascunho.\");await boot(true)}\n catch(x){toast(x.message)}\n};\nwindow.createQ=async function(){\n try{var d=questionPayload();await api(\"create_question\",d);closeM();toast(\"Nova pergunta adicionada em rascunho.\");await boot(true)}\n catch(x){toast(x.message)}\n};\nwindow.publishQ=async function(id){\n var q=S.data.questions.find(function(x){return x.id===id});\n if(!q||q.status!==\"rascunho\")return;\n if(!confirm('Publicar a pergunta \"'+q.titulo+'\"? Ela passa a integrar o formulário dos coordenadores.'))return;\n try{await api(\"publish_question\",{id:id});toast(\"Pergunta publicada.\");await boot(true)}\n catch(x){toast(x.message)}\n};\nwindow.toggleSelfEvaluation=async function(permitida){\n if(!confirm(permitida?\"Permitir a avaliação da própria ficha?\":\"Desativar novas autoavaliações? Histórico preservado.\"))return;\n try{await api(\"set_self_evaluation\",{permitida:permitida});toast(\"Regra atualizada.\");await boot(true)}\n catch(x){toast(x.message)}\n};\nwindow.archiveQ=async function(id){\n var q=S.data.questions.find(x=>x.id===id);if(!q||q.status!==\"rascunho\"){toast(\"Somente perguntas em rascunho podem ser arquivadas.\");return}\n if(!confirm('Arquivar a pergunta \"'+q.titulo+'\"? Ela deixará de aparecer no formulário, mas permanecerá no histórico.'))return;\n try{await api(\"archive_question\",{id:id});toast(\"Pergunta arquivada.\");await boot(true)}\n catch(x){toast(x.message)}\n};\nfunction settings(d){\n var labels={\n \"coordenador.login.bloqueio_minutos\":[\"Bloqueio após falhas de senha\",\"O coordenador fica temporariamente impedido de entrar quando erra a senha várias vezes. Não é um limite de inatividade.\"],\n \"coordenador.login.max_falhas\":[\"Tentativas incorretas permitidas\",\"Número de falhas consecutivas do PIN para um mesmo ROL antes do bloqueio. O bloqueio é da credencial, não só deste dispositivo.\"],\n \"coordenador.sessao.horas\":[\"Duração máxima do acesso\",\"Tempo até uma sessão autenticada expirar. Não tem relação com tentativas erradas de senha.\"],\n \"coordenador.senha.formato\":[\"Formato do PIN inicial\",\"Padrão implementado: PIN de 6 dígitos. Mudar o texto deste campo não gera PINs novos nem modifica os existentes.\"]\n };\n var units={\"coordenador.login.bloqueio_minutos\":\"minutos\",\"coordenador.login.max_falhas\":\"tentativas\",\"coordenador.sessao.horas\":\"horas\",\"coordenador.senha.formato\":\"dígitos\"};\n return'<div class=\"card\" style=\"margin-bottom:12px\"><h3>Política de acesso dos coordenadores</h3><p class=\"muted\">Estas opções são configurações de segurança, não uma lista de senhas. Para consultar ROLs ou gerar um PIN novo, use a aba <b>Contas e PINs</b>.</p></div><div class=\"grid\">'+d.settings.filter(function(x){return Object.prototype.hasOwnProperty.call(labels,x.chave)}).map(function(x){\n var a=labels[x.chave]||[x.chave,x.descricao||\"\"],editable=x.chave!==\"coordenador.senha.formato\",v=typeof x.valor===\"string\"?x.valor:JSON.stringify(x.valor);\n return'<div class=\"card\"><h3>'+e(a[0])+'</h3><p class=\"muted\">'+e(a[1])+'</p><div class=\"field\"><label>Valor atual ('+units[x.chave]+')</label>'+(editable?'<input type=\"number\" min=\"1\" max=\"1440\" id=\"set_'+x.chave.replaceAll(\".\",\"_\")+'\" value=\"'+e(v)+'\">':'<div class=\"code\">PIN de 6 dígitos · formato fixo nesta versão</div>')+'</div>'+(editable?'<button class=\"btn primary small\" onclick=\"saveSetting(&quot;'+x.chave+'&quot;)\">Salvar configuração</button>':'')+'</div>'\n }).join(\"\")+'</div>';\n}\nwindow.saveSetting=async function(k){var id=\"set_\"+k.replaceAll(\".\",\"_\"),v=document.getElementById(id).value;try{await api(\"update_setting\",{chave:k,valor:v});toast(\"Configuração atualizada.\");await boot(true)}catch(x){toast(x.message)}}\nfunction admins(d){return credentialsHtml()+'<div class=\"card\"><div class=\"top\"><div><h3>Contas administrativas</h3><p class=\"muted\">Superadmin controla o sistema. Secretário-Geral trabalha com o Rodízio.</p></div><button class=\"btn primary small\" onclick=\"newAdmin()\">Nova conta</button></div></div><table class=\"table\" style=\"margin-top:10px\"><thead><tr><th>Nome</th><th>E-mail</th><th>Papel</th><th>Estado</th></tr></thead><tbody>'+d.admins.map(function(a){return'<tr><td>'+e(a.nome_exibicao||\"\")+'</td><td>'+e(a.email||\"\")+'</td><td><span class=\"code\">'+e(a.papel)+'</span></td><td>'+(a.ativo?'<span class=\"pill ok\">ativo</span>':'<span class=\"pill\">inativo</span>')+'</td></tr>'}).join(\"\")+'</tbody></table>'}\nwindow.newAdmin=function(){box.innerHTML='<div class=\"ey\">NOVA CONTA ADMINISTRATIVA</div><h2>Provisionar acesso</h2><div class=\"field\"><label>Nome</label><input id=\"an\"></div><div class=\"field\"><label>E-mail</label><input id=\"ae\" type=\"email\"></div><div class=\"field\"><label>Senha inicial</label><input id=\"ap\" type=\"password\"></div><div class=\"field\"><label>Papel</label><select id=\"ar\"><option value=\"secretario_geral\">Secretário-Geral</option><option value=\"revisor\">Revisor</option><option value=\"superadmin\">Superadmin</option></select></div><div class=\"actions\"><button class=\"btn ghost\" onclick=\"closeM()\">Cancelar</button><button class=\"btn primary\" onclick=\"createAdmin()\">Criar conta</button></div>';back.classList.add(\"show\")};\nwindow.createAdmin=async function(){try{await api(\"create_admin\",{nome:document.getElementById(\"an\").value,email:document.getElementById(\"ae\").value,password:document.getElementById(\"ap\").value,papel:document.getElementById(\"ar\").value});closeM();toast(\"Conta criada.\");await boot(true)}catch(x){toast(x.message)}}\nasync function secretariaApi(action,p,retry){\n var x=await fetch(U+\"/functions/v1/rod27-admin\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\",\"Authorization\":\"Bearer \"+S.a},body:JSON.stringify(Object.assign({action:action},p||{}))});\n if(x.status===401&&!retry&&await rf())return secretariaApi(action,p,true);\n var j=await x.json().catch(function(){return{ok:false,error:\"Resposta inválida.\"}});\n if(!x.ok||!j.ok)throw new Error(j.error||\"Não foi possível consultar os acessos.\");\n return j;\n}\nfunction credentialsHtml(){\n var h='<div class=\"card\" style=\"margin-bottom:12px\"><h3>Credenciais dos 42 coordenadores</h3><p class=\"muted\">PINs confirmados podem ser consultados pelo superadmin. Cada consulta é registrada na auditoria.</p></div>';\n if(!S.coordData)return h+'<div class=\"card\" id=\"coordList\">Consultando credenciais…</div>';\n var sectors=S.coordData.sectors||[];\n h+='<div class=\"card\" id=\"coordList\" style=\"overflow-x:auto\"><table class=\"table\"><thead><tr><th>Setor</th><th>Coordenador</th><th>ROL</th><th>Estado</th><th>PIN ATUAL</th><th>Ação</th></tr></thead><tbody>';\n h+=sectors.map(function(x){return'<tr><td>'+e(x.setor)+'</td><td>'+e(x.coordenador)+'</td><td><span class=\"code\">'+e(x.rol)+'</span></td><td>'+e(x.credencial_status)+'</td><td><button class=\"btn ghost small\" onclick=\"showCoordinatorPIN('+Number(x.setor)+')\">Mostrar PIN</button></td><td><button class=\"btn ghost small\" onclick=\"rotateCoordinatorPIN('+Number(x.setor)+')\">Redefinir PIN</button></td></tr>'}).join(\"\");\n return h+'</tbody></table></div>';\n}\nasync function loadCoordinatorAccess(){\n try{S.coordData=await secretariaApi(\"bootstrap\");if(S.tab===\"admins\")render()}\n catch(x){var node=document.getElementById(\"coordList\");if(node)node.textContent=\"Não foi possível consultar os coordenadores: \"+x.message}\n}\nwindow.showCoordinatorPIN=async function(n){\n try{\n  var d=await api(\"show_coordinator_pin\",{setor:n});\n  if(d.status!==\"confirmed\"){toast(\"Verificação pendente.\");return}\n  window._latestPinInfo={rol:String(d.rol),pin:String(d.pin)};\n  box.innerHTML='<div class=\"ey\">PIN ATUAL</div><h2>Setor '+e(n)+'</h2><div class=\"card\"><div class=\"ey\">ROL '+e(d.rol)+'</div><h2 class=\"code\">'+e(d.pin)+'</h2></div><div class=\"actions\"><button class=\"btn primary\" onclick=\"copyNewPin()\">Copiar ROL e PIN</button><button class=\"btn ghost\" onclick=\"closeM()\">Fechar</button></div>';\n  back.classList.add(\"show\");\n }catch(x){toast(x.message)}\n}\nwindow.rotateCoordinatorPIN=async function(n){\n var s=S.coordData&&S.coordData.sectors&&S.coordData.sectors.find(function(x){return Number(x.setor)===Number(n)});\n if(!s){toast(\"Setor não encontrado.\");return}\n if(!confirm(\"Redefinir o PIN do setor \"+n+\" (\"+s.coordenador+\", ROL \"+s.rol+\")? O PIN anterior deixará de funcionar imediatamente e todas as sessões anteriores serão invalidadas.\"))return;\n try{\n  var d=await secretariaApi(\"reset_coordinator_pin\",{setor:n});\n  box.innerHTML='<div class=\"ey\">NOVO PIN GERADO</div><h2>Setor '+e(n)+'</h2><p><b>'+e(s.coordenador)+'</b> · ROL <span class=\"code\">'+e(d.rol)+'</span></p><p class=\"muted\">Este novo PIN aparece apenas uma vez. Copie e entregue ao coordenador por um canal seguro. O PIN antigo já foi substituído.</p><div class=\"card\"><div class=\"ey\">Novo PIN</div><h2 class=\"code\" style=\"letter-spacing:.15em\">'+e(d.pin)+'</h2></div><div class=\"actions\"><button class=\"btn primary\" onclick=\"copyNewPin()\">Copiar ROL e PIN</button><button class=\"btn ghost\" onclick=\"closeM()\">Fechar</button></div>';\n  window._latestPinInfo={rol:String(d.rol),pin:String(d.pin)};\n  back.classList.add(\"show\");\n  S.coordData=await secretariaApi(\"bootstrap\");\n }catch(x){toast(x.message)}\n}\nwindow.copyNewPin=async function(){\n var c=window._latestPinInfo;\n if(!c)return;\n try{await navigator.clipboard.writeText(\"ROL: \"+c.rol+\"\\nPIN: \"+c.pin);toast(\"ROL e PIN copiados.\")}catch(x){toast(\"Copie manualmente o PIN exibido.\")}\n};\nvar AUDIT_AUTH={grant:null};\nfunction audit(d){\n var form=S.auditOpen&&!AUDIT_AUTH.grant?'<div class=\"card\" style=\"margin-bottom:12px\"><div style=\"display:flex;gap:9px;align-items:center\"><input id=\"audit_joint_pass\" aria-label=\"Autorização\" type=\"password\" autocomplete=\"off\" style=\"width:min(360px,80%);border:1px solid var(--line);padding:11px;border-radius:10px\" onkeydown=\"if(event.key===\\'Enter\\'){event.preventDefault();authorizeAudit()}\"><button type=\"button\" class=\"btn ghost\" aria-label=\"Confirmar\" onclick=\"authorizeAudit()\">✓</button></div></div>':\"\";\n return form+d.audit.map(function(a){\n  return '<div class=\"audit\"><strong>'+e(a.acao)+'</strong> · '+e(a.papel||\"\")+'<br><span class=\"muted\">'+e(a.entidade||\"\")+' '+e(a.entidade_id||\"\")+' · '+e(new Date(a.criado_em).toLocaleString(\"pt-BR\"))+'</span>'+\n   (AUDIT_AUTH.grant?'<div class=\"actions\"><button class=\"btn danger small\" onclick=\"openAuditRemoval(&quot;'+e(a.id)+'&quot;)\">Remover registro</button></div>':\"\")+'</div>';\n }).join(\"\");\n}\nwindow.authorizeAudit=async function(){\n var inp=document.getElementById(\"audit_joint_pass\"),pw=inp?inp.value:\"\";\n if(!pw)return;\n try{\n  var result=await api(\"authorize_audit_removal\",{password:pw});\n  AUDIT_AUTH.grant=result.grant;S.auditOpen=false;inp.value=\"\";render();\n }catch(err){\n  AUDIT_AUTH.grant=null;\n  S.auditOpen=false;\n  if(inp)inp.value=\"\";\n  render();\n }\n};\nwindow.openAuditRemoval=function(id){\n if(!AUDIT_AUTH.grant)return;\n box.innerHTML='<div class=\"ey\">CONTROLE SUPERIOR · REGISTRO DE AUDITORIA</div><h2>Exclusão administrativa</h2><p class=\"muted\">O conteúdo deste registro será excluído. Permanecerá o registro mínimo de que a exclusão foi autorizada, por quem foi solicitada e qual foi a justificativa. Esta ação não desfaz a operação original.</p><div class=\"field\"><label>Quem determinou a exclusão?</label><input id=\"audit_requested_by\" maxlength=\"160\" placeholder=\"Autoridade solicitante\"></div><div class=\"field\"><label>Motivo e referência da determinação</label><textarea id=\"audit_reason\" rows=\"4\" maxlength=\"2000\" placeholder=\"Registre a razão da exclusão\"></textarea></div><div class=\"actions\"><button class=\"btn ghost\" onclick=\"closeM()\">Cancelar</button><button class=\"btn danger\" onclick=\"removeAuditEntry(&quot;'+e(id)+'&quot;)\">Confirmar exclusão</button></div>';\n back.classList.add(\"show\");\n};\nwindow.removeAuditEntry=async function(id){\n var by=document.getElementById(\"audit_requested_by\").value.trim(),why=document.getElementById(\"audit_reason\").value.trim();\n if(by.length<3||why.length<12){toast(\"Informe o solicitante e o motivo da exclusão.\");return}\n if(!confirm(\"Excluir este registro do histórico comum? A exclusão terá uma trilha administrativa própria.\"))return;\n try{await api(\"remove_audit_entry\",{registro_id:id,solicitante:by,motivo:why,grant:AUDIT_AUTH.grant});closeM();toast(\"Registro excluído. A exclusão foi auditada.\");await boot(true)}\n catch(err){AUDIT_AUTH.grant=null;closeM();await boot(true);toast(\"Autorização inválida ou expirada. Valide novamente.\")}\n};\nwindow.revokeAll=async function(){if(!confirm(\"Encerrar todas as sessões ativas dos coordenadores? Eles precisarão entrar novamente.\"))return;try{await api(\"revoke_all_coordinator_sessions\");toast(\"Sessões encerradas.\");await boot(true)}catch(x){toast(x.message)}}\nasync function boot(silent){S.a=sessionStorage.getItem(\"ctl_a\")||S.a;S.r=sessionStorage.getItem(\"ctl_r\")||S.r;if(!S.a){login();return}try{S.data=await api(\"bootstrap\");render();if(S.tab===\"overview\")refreshHealth(false)}catch(x){if(!silent){clr();login(x.message)}else toast(x.message)}}\nboot();\n</script></body></html>";
const cors={"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"content-type, authorization","Access-Control-Allow-Methods":"GET, POST, OPTIONS"};
function json(data:unknown,status=200){return new Response(JSON.stringify(data),{status,headers:{...cors,"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"}})}function fail(message:string,status=400){return json({ok:false,error:message},status)}
async function ctx(req:Request){const h=req.headers.get("authorization")??"";if(!h.startsWith("Bearer "))return null;const{data,error}=await db.auth.getUser(h.slice(7).trim());if(error||!data.user)return null;const{data:a}=await db.from("usuarios_admin").select("user_id,papel,nome_exibicao,ativo").eq("user_id",data.user.id).eq("ativo",true).maybeSingle();return a&&["superadmin1","superadmin"].includes(a.papel)?{user:data.user,admin:a}:null}
function isSuperadmin1(c:any){return c.admin.papel==="superadmin1"}
const SHA256=async(text:string)=>Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(text)))).map(x=>x.toString(16).padStart(2,"0")).join("");
function currentSessionId(req:Request):string{
 const jwt=(req.headers.get("authorization")??"").replace(/^Bearer\s+/,"").trim();
 try{
  const part=jwt.split(".")[1]??"",decoded=atob(part.replace(/-/g,"+").replace(/_/g,"/"));
  const sid=String(JSON.parse(decoded).session_id??"");
  if(!/^[a-f0-9-]{36}$/i.test(sid))throw Error("invalid session");
  return sid;
 }catch{throw Error("Sessão administrativa inválida.");}
}
async function issueAuditGrant(c:any,b:any,req:Request){
 const password=String(b.password??"");
 if(!password||password.length>1000)throw Error("Autorização inválida.");
 const {data:admins,error:aerr}=await db.from("usuarios_admin").select("user_id").eq("papel","secretario_geral").eq("ativo",true);
 if(aerr||admins?.length!==1)throw Error("Autorizador administrativo indisponível.");
 const uid=admins[0].user_id;
 if(uid===c.user.id)throw Error("Duas contas distintas são necessárias.");
 const {data:userData,error:userError}=await db.auth.admin.getUserById(uid);
 const email=userData.user?.email;
 if(userError||!email)throw Error("Autorizador indisponível.");
 const verifier=createClient(URL,KEY,{auth:{persistSession:false,autoRefreshToken:false}});
 const {data:login,error:loginError}=await verifier.auth.signInWithPassword({email,password});
 if(loginError||login.user?.id!==uid||!login.session)throw Error("Autorização recusada.");
 await verifier.auth.signOut({scope:"local"}).catch(()=>{});
 const bytes=crypto.getRandomValues(new Uint8Array(32));
 const token=Array.from(bytes).map(x=>x.toString(16).padStart(2,"0")).join("");
 const {error:grantError}=await db.rpc("rod27_issue_joint_audit_grant",{
  p_superadmin:c.user.id,p_secretario:uid,p_session:currentSessionId(req),p_token_hash:await SHA256(token)
 });
 if(grantError)throw grantError;
 return{ok:true,grant:token};
}
async function removeAuditEntry(c:any,b:any,req:Request){
 const id=String(b.registro_id??"").trim();
 if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id))
  throw new Error("Registro de auditoria inválido.");
 const orderedBy=String(b.solicitante??"").trim(), reason=String(b.motivo??"").trim();
 const grant=String(b.grant??"");
 if(!/^[0-9a-f]{64}$/.test(grant))throw Error("Autorização conjunta obrigatória.");
 if(orderedBy.length<3||orderedBy.length>160||reason.length<12||reason.length>2000)
  throw new Error("Informe quem solicitou e justifique a exclusão (mínimo 12 caracteres).");
 const{data,error}=await db.rpc("rod27_remove_audit_entry_joint",{
  p_registro:id,p_admin:c.user.id,p_solicitante:orderedBy,p_motivo:reason,
  p_session:currentSessionId(req),p_token_hash:await SHA256(grant)
 });
 if(error)throw error;
 return{ok:true,result:data};
}
async function audit(c:any,acao:string,entidade:string,id:string,detalhes:any={}){await db.from("auditoria_sistema").insert({user_id:c.user.id,papel:c.admin.papel,acao,entidade,entidade_id:id,detalhes})}
async function operationalHealth(req:Request){
 const probe=async(id:string,title:string,url:string,accepted:number[]= [200],method="GET",body?:string)=>{
  const started=Date.now();
  try{
   const headers:Record<string,string>={"cache-control":"no-cache"};
   if(id==="auth")headers["apikey"]=KEY;
   if(method==="POST"){headers["Content-Type"]="application/json";headers["Authorization"]=req.headers.get("authorization")??""}
   const response=await fetch(url,{method,headers,body,cache:"no-store",signal:AbortSignal.timeout(7000)});
   let ok=accepted.includes(response.status);
   if(id==="admin_backend"&&ok){
    const data=await response.json().catch(()=>({ok:false}));
    ok=data.ok===true&&!!data.admin;
   }
   return{id,title,ok,http:response.status,ms:Date.now()-started};
  }catch(err){
   return{id,title,ok:false,http:null,ms:Date.now()-started,
    error:err instanceof Error?err.name:"Indisponível"};
  }
 };
 const site="https://rod27-ieadern.pages.dev",base="https://zrjxxcytgtjuuinhkfux.supabase.co";
 const calls=[
  probe("root","Raiz protegida",site+"/",[404]),
  probe("coordinator_page","Página dos coordenadores",site+"/coordenador"),
  probe("secretary_page","Página da Secretaria",site+"/secretaria"),
  probe("control_page","Página do Controle",site+"/controle"),
  probe("onboarding_page","Página de primeiro acesso",site+"/primeiro-acesso"),
  probe("recovery_page","Página de recuperação",site+"/redefinir-senha"),
  probe("auth","Autenticação Supabase",base+"/auth/v1/settings"),
  probe("coordinator_backend","Função dos coordenadores",base+"/functions/v1/rod27-coordinator",[200]),
  probe("onboarding_backend","Função de primeiro acesso",base+"/functions/v1/rod27-first-access",[200]),
  probe("admin_backend","Função da Secretaria (autenticada)",base+"/functions/v1/rod27-admin",[200],"POST",JSON.stringify({action:"bootstrap"}))
 ];
 const [checks,heartbeat,sessions]=await Promise.all([
  Promise.all(calls),
  db.rpc("rod27_heartbeat"),
  db.rpc("rod27_operational_sessions")
 ]);
 const allChecks=[...checks,{
  id:"control_backend",title:"Função de Controle (autenticada)",ok:true,http:200,ms:null
 },{
  id:"database",title:"Banco Postgres",ok:!heartbeat.error&&Array.isArray(heartbeat.data)&&heartbeat.data[0]?.ok===true,
  http:null,ms:null,error:heartbeat.error?"Consulta falhou":undefined
 },{
  id:"sessions",title:"Leitura de sessões",ok:!sessions.error&&!!sessions.data,
  http:null,ms:null,error:sessions.error?"Consulta falhou":undefined
 }];
 const list= sessions.error?{checked_at:null,administrators:[],coordinators:[]}:(sessions.data??{administrators:[],coordinators:[]});
 return {ok:true,checked_at:new Date().toISOString(),checks:allChecks,
  healthy:allChecks.every((x:any)=>x.ok),issues:allChecks.filter((x:any)=>!x.ok).length,
  sessions:list,notes:"Verificações de acesso e consultas; não substituem testes completos de preenchimento e envio."};
}
async function bootstrap(c:any){const[{data:health,error:hErr},{data:questions},{data:settings},{data:admins},{data:logs}]=await Promise.all([db.rpc("rod27_system_health"),db.from("perguntas_avaliacao").select("id,codigo,ordem,categoria,titulo,enunciado,tipo_resposta,opcoes,obrigatoria,versao,status,ativa").order("ordem"),db.from("configuracoes_sistema_runtime").select("chave,valor,descricao,atualizado_em").order("chave"),db.from("usuarios_admin").select("user_id,papel,nome_exibicao,ativo,criado_em").order("criado_em"),db.from("auditoria_sistema").select("id,papel,acao,entidade,entidade_id,detalhes,criado_em").order("criado_em",{ascending:false}).limit(60)]);if(hErr)throw hErr;
const [pagesQ,ownQ,invitesQ]=await Promise.all([
  db.from("paginas_coordenador").select("id",{head:true,count:"exact"}).eq("ativa",true),
  db.from("avaliacoes_dirigente").select("id",{head:true,count:"exact"}).eq("eh_proprio_coordenador",true),
  db.from("admin_convites").select("id",{head:true,count:"exact"}).is("usado_em",null).gt("expira_em",new Date().toISOString())
]);
if(pagesQ.error||ownQ.error||invitesQ.error)throw new Error("Falha ao consultar verificações de prontidão.");
const{data:selfOption,error:selfOptionError}=await db.from("configuracoes_sistema_runtime").select("valor").eq("chave","avaliacao.autoavaliacao.permitida").maybeSingle();
if(selfOptionError)throw selfOptionError;
const selfAllowed=selfOption?.valor?.permitida===true;
const validInvites=invitesQ.count??0,ownCount=ownQ.count??0,activePages=pagesQ.count??0,published=(questions??[]).filter((x:any)=>x.ativa && x.status==="publicada").length;
const checks=[
  {id:"base",title:"Base de setores e congregações",ok:Number(health.setores)===42&&Number(health.congregacoes)===253,detail:`${health.setores} setores e ${health.congregacoes} congregações cadastradas`},
  {id:"coordinator_pages",title:"Páginas individuais dos coordenadores",ok:activePages===42,detail:`${activePages} de 42 páginas ativas`},
  {id:"questions",title:"Publicação do formulário",ok:published>0,detail:`${published} perguntas publicadas; ${(questions??[]).filter((x:any)=>x.status==="rascunho").length} em rascunho`},
  {id:"administrators",title:"Primeiro acesso administrativo",ok:Number(health.admins)>=2,detail:`${health.admins} contas ativas; ${validInvites} convites válidos ainda não utilizados`},
  {id:"coordinator_access",title:"Liberação de credenciais",ok:Number(health.credenciais_ativas)===42,detail:`${health.credenciais_ativas} de 42 coordenadores com acesso liberado`},
  {id:"own_coordinator",title:"Feedback dos coordenadores ao pastor",ok:ownCount===42,detail:String(ownCount)+" fichas próprias identificadas para manifestação separada"}
];
const readiness={checks,ready_for_launch:checks.every((x:any)=>x.ok),checked_at:new Date().toISOString()};
const users:any[]=[];for(const a of admins??[]){const{data:u}=await db.auth.admin.getUserById(a.user_id);users.push({...a,email:u.user?.email??null})}return{ok:true,admin:{email:c.user.email,nome_exibicao:c.admin.nome_exibicao,papel:c.admin.papel},health,readiness,questions:questions??[],settings:settings??[],admins:isSuperadmin1(c)?users:[],audit:logs??[]}}
function validateQuestionInput(b:any,previous:any=null){
 const titulo=String(b.titulo??previous?.titulo??"").trim();
 const enunciado=String(b.enunciado??previous?.enunciado??"").trim();
 if(!titulo||!enunciado||titulo.length>180||enunciado.length>4000)throw new Error("Título e pergunta são obrigatórios (até 180 e 4.000 caracteres).");
 const tipo_resposta=String(b.tipo_resposta??previous?.tipo_resposta??"texto_longo");
 if(!["texto_longo","escolha_unica"].includes(tipo_resposta))throw new Error("Tipo de resposta não suportado.");
 const obrigatoria=b.obrigatoria===undefined?(previous?.obrigatoria??true):b.obrigatoria;
 if(typeof obrigatoria!=="boolean")throw new Error("A obrigatoriedade precisa ser verdadeira ou falsa.");
 let opcoes:string[]|null=null;
 if(tipo_resposta==="escolha_unica"){
  const raw=b.opcoes===undefined?previous?.opcoes:b.opcoes;
  if(!Array.isArray(raw))throw new Error("Informe as alternativas da pergunta.");
  opcoes=raw.map((v:any)=>String(v).trim());
  if(opcoes.length<2||opcoes.length>12||opcoes.some(v=>!v||v.length>120)||new Set(opcoes.map(v=>v.toLowerCase())).size!==opcoes.length)throw new Error("Informe de 2 a 12 alternativas distintas, com até 120 caracteres cada.");
 }
 return{titulo,enunciado,tipo_resposta,opcoes,obrigatoria};
}
async function ensureCycleWithoutAnswers(cycleId:string) {
 const{count:started,error:startedError}=await db.from("avaliacoes_dirigente")
   .select("id",{head:true,count:"exact"}).eq("ciclo_id",cycleId).neq("status","nao_iniciada");
 if(startedError)throw startedError;
 // Any started evaluation in this cycle prohibits structural changes.
 if(started)throw new Error("Há avaliações iniciadas. Não é permitido alterar ou publicar novas perguntas sem versionamento.");
 // Verify existing answers directly through a database-side protected RPC.
 const{data:lockStatus,error:statusError}=await db.rpc("rod27_cycle_has_answers",{p_ciclo:cycleId});
 if(statusError)throw statusError;
 if(lockStatus)throw new Error("Existem respostas salvas. A alteração requer uma nova versão do formulário.");
}
async function updateQuestion(c:any,b:any){
 const id=String(b.id??"");
 const{data:q,error:readErr}=await db.from("perguntas_avaliacao").select("id,ciclo_id,status,ativa,versao,titulo,enunciado,tipo_resposta,opcoes,obrigatoria").eq("id",id).maybeSingle();
 if(readErr)throw readErr;
 if(!q)throw new Error("Pergunta não encontrada.");
 if(!q.ativa||!["rascunho","publicada"].includes(q.status))throw new Error("Pergunta arquivada não pode ser alterada.");
 // Alterações publicadas criam nova versão sem modificar avaliações já iniciadas.
 const payload=validateQuestionInput(b,q);
 const{error}=await db.from("perguntas_avaliacao").update({...payload,atualizado_em:new Date().toISOString()}) .eq("id",id).eq("status",q.status).eq("ativa",true);
 if(error)throw error;
 await audit(c,q.status==="publicada"?"update_published_question_before_first_answer":"update_question","perguntas_avaliacao",id,{codigo:q.codigo??null,versao:q.versao,antes:{titulo:q.titulo,enunciado:q.enunciado,tipo_resposta:q.tipo_resposta,opcoes:q.opcoes,obrigatoria:q.obrigatoria},depois:payload});
 return{ok:true};
}
async function createQuestion(c:any,b:any){
 const payload=validateQuestionInput(b);
 const{data:cycle,error:cycleErr}=await db.from("ciclos_rodizio").select("id").eq("ano",2027).single();
 if(cycleErr||!cycle)throw cycleErr??new Error("Ciclo 2027 não encontrado.");
 const{data:highest,error:ordErr}=await db.from("perguntas_avaliacao").select("ordem").eq("ciclo_id",cycle.id).order("ordem",{ascending:false}).limit(1);
 if(ordErr)throw ordErr;
 const ordem=(highest?.[0]?.ordem??0)+1;
 if(ordem>100)throw new Error("Limite de perguntas atingido.");
 const codigo="AD"+crypto.randomUUID().replaceAll("-","").slice(0,10).toUpperCase();
 const{data:row,error}=await db.from("perguntas_avaliacao").insert({ciclo_id:cycle.id,codigo,versao:1,ordem,categoria:"geral",...payload,ativa:true,status:"rascunho"}).select("id").single();
 if(error||!row)throw error??new Error("Falha ao criar pergunta.");
 await audit(c,"create_question","perguntas_avaliacao",row.id,{codigo,ordem,...payload});
 return{ok:true,id:row.id};
}
async function publishQuestion(c:any,b:any){
 const id=String(b.id??"");
 const{data:q,error:err}=await db.from("perguntas_avaliacao")
  .select("id,ciclo_id,codigo,status,ativa,titulo,tipo_resposta,opcoes")
  .eq("id",id).maybeSingle();
 if(err||!q)throw err??new Error("Pergunta não encontrada.");
 if(q.status!=="rascunho"||!q.ativa)throw new Error("Somente rascunhos podem ser publicados.");
 // Publicar novo item cria versão, mantendo os formulários antigos.
 const{error}=await db.from("perguntas_avaliacao").update({status:"publicada",atualizado_em:new Date().toISOString()}).eq("id",id).eq("status","rascunho");
 if(error)throw error;
 await audit(c,"publish_question","perguntas_avaliacao",id,{codigo:q.codigo,titulo:q.titulo});
 return{ok:true};
}
async function setSelfEvaluation(_c:any,_b:any){throw new Error("Não existe autoavaliação de desempenho. O feedback próprio é enviado pela Manifestação de Interesse.");}
async function archiveQuestion(c:any,b:any){
 const id=String(b.id??"");
 const{data:q,error:readErr}=await db.from("perguntas_avaliacao").select("id,codigo,titulo,status,ativa").eq("id",id).maybeSingle();
 if(readErr||!q)throw readErr??new Error("Pergunta não encontrada.");
 if(q.status!=="rascunho"||!q.ativa)throw new Error("Somente perguntas ativas em rascunho podem ser arquivadas.");
 const{count,error:refErr}=await db.from("respostas_avaliacao").select("id",{head:true,count:"exact"}).eq("pergunta_id",id);
 if(refErr)throw refErr;
 if(count)throw new Error("A pergunta possui respostas e não pode ser arquivada.");
 const{error}=await db.from("perguntas_avaliacao").update({status:"arquivada",ativa:false,atualizado_em:new Date().toISOString()}).eq("id",id).eq("status","rascunho");
 if(error)throw error;
 await audit(c,"archive_question","perguntas_avaliacao",id,{codigo:q.codigo,titulo:q.titulo});
 return{ok:true};
}
async function updateSetting(c:any,b:any){const key=String(b.chave??""),allowed=["coordenador.login.max_falhas","coordenador.login.bloqueio_minutos","coordenador.sessao.horas","coordenador.senha.formato"];if(!allowed.includes(key))throw new Error("Configuração não editável.");let value:any=String(b.valor??"").trim();if(key!=="coordenador.senha.formato"){const n=Number(value);if(!Number.isFinite(n)||n<=0||n>1440)throw new Error("Valor numérico inválido.");value=n}else if(value!=="pin_6_digitos")throw new Error("Formato ainda não suportado.");const{error}=await db.from("configuracoes_sistema_runtime").update({valor:value,atualizado_por:c.user.id,atualizado_em:new Date().toISOString()}).eq("chave",key);if(error)throw error;await audit(c,"update_setting","configuracoes_sistema_runtime",key,{valor:value});return{ok:true}}
async function createAdmin(c:any,b:any){const email=String(b.email??"").trim().toLowerCase(),password=String(b.password??""),nome=String(b.nome??"").trim(),papel=String(b.papel??"");if(!email||password.length<10||!["superadmin","secretario_geral","revisor"].includes(papel))throw new Error("Dados inválidos. Use senha com pelo menos 10 caracteres.");const{data,error}=await db.auth.admin.createUser({email,password,email_confirm:true});if(error||!data.user)throw error??new Error("Falha ao criar usuário.");const{error:iErr}=await db.from("usuarios_admin").insert({user_id:data.user.id,papel,nome_exibicao:nome||null,ativo:true});if(iErr){await db.auth.admin.deleteUser(data.user.id);throw iErr}await audit(c,"create_admin","usuarios_admin",data.user.id,{email,papel,nome});return{ok:true,user_id:data.user.id}}
async function revokeAll(c:any){const now=new Date().toISOString();const{error}=await db.from("coordenador_sessoes").update({revogada_em:now}).is("revogada_em",null);if(error)throw error;await audit(c,"revoke_all_coordinator_sessions","coordenador_sessoes","all",{});return{ok:true}}
async function showCoordinatorPin(c:any,b:any){
 const n=Number(b.setor);
 if(!Number.isInteger(n)||n<1||n>42)throw new Error("Setor inválido.");
 const {data:cycle,error:cycleError}=await db.from("ciclos_rodizio").select("id").eq("ano",2027).single();
 if(cycleError)throw cycleError;
 const {data:sector,error:sectorError}=await db.from("setores").select("id").eq("numero",n).single();
 if(sectorError)throw sectorError;
 const {data:coord,error:coordError}=await db.from("coordenacoes_setor").select("id").eq("ciclo_id",cycle.id).eq("setor_id",sector.id).single();
 if(coordError)throw coordError;
 const {data:cred,error:credError}=await db.from("coordenador_credenciais").select("id").eq("coordenacao_id",coord.id).single();
 if(credError)throw credError;
 const {data,error}=await db.rpc("rod27_get_coordinator_pin",{p_cred_id:cred.id,p_admin:c.user.id});
 if(error)throw error;
 return data?.[0]?{ok:true,status:"confirmed",rol:data[0].rol,pin:data[0].pin}:{ok:true,status:"pending"};
}
async function handle(req:Request){const c=await ctx(req);if(!c)return fail("Acesso restrito ao superadmin.",403);let b:any;try{b=await req.json()}catch{return fail("Requisição inválida.",400)}try{switch(String(b.action??"")){case"bootstrap":return json(await bootstrap(c));case"operational_health":return json(await operationalHealth(req));case"show_coordinator_pin":if(!isSuperadmin1(c))return fail("Acesso exclusivo do superadmin1.",403);return json(await showCoordinatorPin(c,b));case"update_question":return json(await updateQuestion(c,b));case"create_question":return json(await createQuestion(c,b));case"archive_question":return json(await archiveQuestion(c,b));case"publish_question":return json(await publishQuestion(c,b));case"set_self_evaluation":return json(await setSelfEvaluation(c,b));case"update_setting":return json(await updateSetting(c,b));case"create_admin":if(!isSuperadmin1(c))return fail("Acesso exclusivo do superadmin1.",403);return json(await createAdmin(c,b));case"authorize_audit_removal":if(!isSuperadmin1(c))return fail("Acesso exclusivo do superadmin1.",403);return json(await issueAuditGrant(c,b,req));case"remove_audit_entry":if(!isSuperadmin1(c))return fail("Acesso exclusivo do superadmin1.",403);return json(await removeAuditEntry(c,b,req));case"revoke_all_coordinator_sessions":return json(await revokeAll(c));default:return fail("Ação desconhecida.",400)}}catch(e){console.error(e);return fail(e instanceof Error?e.message:"Falha de controle.",500)}}
Deno.serve(async(req:Request)=>{if(req.method==="OPTIONS")return new Response("ok",{headers:cors});if(req.method==="GET")return Response.redirect("https://rod27-ieadern.pages.dev/controle",302);if(req.method==="POST")return handle(req);return new Response("Method not allowed",{status:405,headers:cors})});